BEGIN;

-- Manually reviewed cleanup of literal \\n markers in reference prose.
-- A literal \\n is allowed only immediately after a period.
CREATE TEMP TABLE _prose_newline_fix (
  table_name text NOT NULL,
  row_id bigint NOT NULL,
  column_name text NOT NULL,
  old_value text NOT NULL,
  new_value text NOT NULL
) ON COMMIT DROP;


CREATE TEMP TABLE _prose_columns (table_name text NOT NULL, column_name text NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  r record;
  current_value text;
BEGIN
  FOR r IN SELECT * FROM _prose_newline_fix ORDER BY table_name, row_id, column_name LOOP
    EXECUTE format('SELECT %I FROM %I WHERE id = $1', r.column_name, r.table_name)
      INTO current_value USING r.row_id;
    IF current_value IS DISTINCT FROM r.old_value THEN
      RAISE EXCEPTION 'Prose newline cleanup source mismatch at %.% id=%',
        r.table_name, r.column_name, r.row_id;
    END IF;
  END LOOP;
END $$;

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT * FROM _prose_newline_fix ORDER BY table_name, row_id, column_name LOOP
    EXECUTE format('UPDATE %I SET %I = $1 WHERE id = $2', r.table_name, r.column_name)
      USING r.new_value, r.row_id;
  END LOOP;
END $$;

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT DISTINCT table_name, row_id
    FROM _prose_newline_fix
    ORDER BY table_name, row_id
  LOOP
    EXECUTE format(
      'UPDATE %I SET "version" = COALESCE("version", 0) + 1, "updatedAt" = now() WHERE id = $1',
      r.table_name
    ) USING r.row_id;
  END LOOP;
END $$;

DO $$
DECLARE
  r record;
  invalid_count bigint;
BEGIN
  FOR r IN SELECT * FROM _prose_columns ORDER BY table_name, column_name LOOP
    EXECUTE format(
      'SELECT count(*) FROM %I WHERE %I IS NOT NULL AND position(E''\\n'' in replace(%I, ''.'' || E''\\n'', '''')) > 0',
      r.table_name, r.column_name, r.column_name
    ) INTO invalid_count;
    IF invalid_count <> 0 THEN
      RAISE EXCEPTION 'Invalid literal newline remains in %.%: % row(s)',
        r.table_name, r.column_name, invalid_count;
    END IF;
  END LOOP;
END $$;

-- Migration version.
VALUES ('characters_mirror', '20261008091313220-prose-newline-normalization', now())
ON CONFLICT ("module") DO UPDATE
SET "version" = '20261008091313220-prose-newline-normalization', "timestamp" = now();

VALUES ('serverpod', '20240516151843329', now())
ON CONFLICT ("module") DO UPDATE
SET "version" = '20240516151843329', "timestamp" = now();

VALUES ('serverpod_auth', '20240520102713718', now())
ON CONFLICT ("module") DO UPDATE
SET "version" = '20240520102713718', "timestamp" = now();

COMMIT;
